    n = int(num(vars.get('product_count')))
    vars['cur_slot'] = str(k)
    cd = str(vars.get('carry_date') or '')
    pw = str(vars.get('m_today_when_%d' % k) or '')
    pa = num(vars.get('m_today_amount_%d' % k), 0.0)
