        vars[P['rv']] = 'auto'
    elif str(vars.get('floor_first') or '') == '1' and k == 1:
        vars['floor_first'] = ''
        vars[P['rv']] = 'ask_floor'
    else:
        vars[P['rv']] = 'ask'
except Exception:
    vars[P['rv']] = 'error'

