    # (mov_k = 1); a date after the product's deadline moves to the deadline (adj_k = 1). Returns the ISO date or ''.
    today = day_today()
    if d is None or d < today:
        return ''
    mov = ''
    while not bizday(d):
        d = d + datetime.timedelta(days=1)
        mov = '1'
    s = d.isoformat()
    dl = str(vars.get('s%d_deadline' % k) or '')
    adj = ''
    if dl != '' and s > dl:
        s = dl
        adj = '1'
        mov = ''
    vars['date_%d' % k] = s
    vars['adj_%d' % k] = adj
    vars['mov_%d' % k] = mov
    return s

